import { TransformResult, LoadResult } from './types';

export type { LoadResult };

export async function loadRecord(
  tableName: string,
  record: TransformResult
): Promise<LoadResult> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (!tableName) {
        reject(new Error('Missing destination table name'));
        return;
      }
      if (record.id < 0) {
        reject(new Error(`Duplicate key violation in table ${tableName}: ${record.id}`));
        return;
      }
      resolve({
        insertedId: record.id,
        table: tableName,
        success: true,
      });
    }, 10);
  });
}

export const load = loadRecord;

